    private static byte[] Block(string base64) => Convert.FromBase64String(base64);

    [Theory]
    [InlineData(nameof(Wall2401144), 3524, 7918308)]   // JoinEnd step with a two-entry exposed face map, then a pair step
    [InlineData(nameof(Wall5549128), 1913, 5549461)]   // pair step whose counted face table is also a terminated 20-byte table
    public void HostBlockWithAnAmbiguousOrWideStepTable_IsReadByTheLayoutSearch(string name, int classId, int cutter)
    {
        var block = Block(name == nameof(Wall2401144) ? Wall2401144 : Wall5549128);
        uint size = (uint)(block.Length - 16);

        // the exact reading (the one the legacy profile paths use) is unchanged: it cannot decode these
        Assert.Null(TfBlockDeserializer.ExtractCuttingElementIdsAndSteps(block, 0, size, (ushort)classId, out var exact));
        Assert.Null(exact);

        var steps = TfBlockDeserializer.ExtractCutOutStepsWithLayoutSearch(block, 0, size, (ushort)classId);
        Assert.Equal([((ushort)977, cutter, false)], steps);
    }

    [Fact]
    public void PairStepWithMergedFaceInfo_IsReadByTheLayoutSearch()
    {
        // CutPairGStep.m_mergedFaceInfo persists [count][count x 12 bytes] (two entries here); read as 4-byte entries the
        // cursor lands inside the next step.
        var block = Block(Wall2722763);
        uint size = (uint)(block.Length - 16);

        Assert.Null(TfBlockDeserializer.ExtractCuttingElementIdsAndSteps(block, 0, size, 3524, out _));

        var steps = TfBlockDeserializer.ExtractCutOutStepsWithLayoutSearch(block, 0, size, 3524);
        Assert.Equal([((ushort)4137, 2722764, true), ((ushort)977, 7652932, false), ((ushort)977, 7724851, false),
            ((ushort)977, 7724852, false)], steps);
    }

    [Fact]
    public void TruncatedBlock_IsNotRead()
    {
        var block = Block(Wall2401144);
        var cut = block[..(block.Length - 40)];
        Assert.Null(TfBlockDeserializer.ExtractCutOutStepsWithLayoutSearch(cut, 0, (uint)(cut.Length - 16), 3524));
    }
